  display: block !important;
}

/* ======================================================
   ⌨️ 底栏设置 (纯色 #EAEAEA) + 防遮挡布局
   ====================================================== */
:root {
  --input-area-bg: #EAEAEA; 

  /* 👇 彻底干掉底栏的灰色分割线 */
  --input-area-border-top: none; 

