/* ======================================================
   ⌨️ 底栏设置 (纯色 #FDF4F9) + 防遮挡布局
   ====================================================== */
:root {
  --input-area-bg: #FDF4F9; 

  /* 👇 彻底干掉底栏的灰色分割线 */
  --input-area-border-top: none; 

