}

/* =======================================
   💬 1️⃣ 气泡核心设置 (微圆角长方形 + 极细顶条)
   ======================================= */
:root {
  /* 👇 缩小气泡内间距 (上下8px，左右12px) */
  --bubble-me-padding: 7px 12px;
  --bubble-them-padding: 7px 12px;

  /* 👇 告别锋利直角：加上 4px 的微小柔和圆角 */
