  --bubble-them-radius: 2px !important;

  /* 👇 我方文字颜色改为深灰色 */
  --bubble-me-color: #333333 !important;
  --bubble-them-color: #000000 !important;

  --bubble-me-border: none !important;
  --bubble-them-border: none !important;
  --bubble-me-shadow: none !important;
  --bubble-them-shadow: none !important;
}

/* 强制隐藏系统自带的气泡小三角 */
.bubble-me-custom::after,
.bubble-them-custom::after {
  display: none !important;
}

/* 🟢 对方气泡：整体纯白，顶部 4px 浅灰细条 */
.bubble-them-custom {
  background-color: #FFFFFF !important;
  position: relative !important;
  overflow: hidden !important; 
}
.bubble-them-custom::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px; /* 缩小顶部色条 */
  background-color: #F4F4F4 !important;
  border-radius: 2px 2px 0 0 !important; /* 跟随气泡的微圆角 */
  z-index: 0 !important;
}

/* 🟣 我方气泡：整体浅灰，顶部 4px 纯白细条 */
.bubble-me-custom {
  background-color: #F4F4F4 !important;
  position: relative !important;
  overflow: hidden !important;
}
.bubble-me-custom::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px; /* 缩小顶部色条 */
  background-color: #FFFFFF !important;
  border-radius: 2px 2px 0 0 !important;
  z-index: 0 !important;
}

