.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-me-custom:has(.msg-image-wrapper),
.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-me-custom:has(.msg-transfer-card),
.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-me-custom:has(.msg-call-card),
