.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-them-custom:has(.msg-image-wrapper),
.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-them-custom:has(.msg-transfer-card),
.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-them-custom:has(.msg-call-card),
.chat-detail-screen .msg-bubble-wrapper .msg-content-stack .bubble-them-custom:has([class*="call"]),
