    --chat-header-unread-num-color: #000000;
    --chat-header-unread-num-size: 10px;
    --chat-header-unread-num-weight: 700;
    --chat-header-unread-num-padding: 2px 6px;
    --chat-header-unread-num-radius: 12px;
    --chat-header-unread-num-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
    --chat-header-unread-num-top: 12px;
    --chat-header-unread-num-left: 28px;

    --chat-header-unread-bg: #ff3b30;
    --chat-header-unread-size: 6px;
    --chat-header-unread-shadow: 0 1px 2px rgba(255, 59, 48, 0.5);
    --chat-header-unread-top: 10px;
