  display: block !important;
}

/* ======================================================
   ⌨️ 底栏设置 (纯色 #E2EEFA) + 防遮挡布局
   ====================================================== */
:root {
  --input-area-bg: #E2EEFA; 

  /* 👇 彻底干掉底栏的灰色分割线 */
  --input-area-border-top: none; 

  --input-area-blur: 0px; 
  --input-area-min-height: 75px; 
