  width: auto !important;
}
.chat-detail-screen .msg-image-wrapper img {
  max-width: 100% !important;
  height: auto !important;
  border-radius: 8px !important; 
}

/* 👇 暴力镇压表情包、贴纸、动图尺寸 (进一步压制到 75px) */
.chat-detail-screen .msg-bubble-container img.emoji,
.chat-detail-screen .msg-bubble-container img[class*="sticker"],
.chat-detail-screen .msg-bubble-container img[src*="sticker"],
.chat-detail-screen .msg-bubble-container img[src*="giphy"],
