/* =======================================
   🏷️ 8️⃣ 头像旁自定义名字 (仅在连发首条显示)
   ======================================= */
/* 整体气泡往下挪一点点，给顶部要写的文字留出空间 */
.chat-detail-screen .msg-bubble-wrapper.is-first,
.chat-detail-screen .msg-bubble-wrapper.is-single {
  margin-top: 18px !important; 
}

/* 对方头顶文字 */
.msg-avatar-them-container::before {
  content: "(ㅇㅈㅇ)딩동..🤍";
  position: absolute;
  top: -18px;          /* 悬浮在头像正上方 */
  left: 25px;
  white-space: nowrap; /* 保证文字不换行 */
  font-size: 11px;     /* 👈 调整文字大小 */
  color: #a9a9a9;      /* 👈 调整文字色号 (浅灰) */
  pointer-events: none;
}

/* 我方头顶文字 */
.msg-avatar-me-container::before {
  content: "☆₊⋆행운이 오고⋆♪";
  position: absolute;
  top: -18px;
  right: 25px;            /* 靠右对齐 */
  white-space: nowrap;
  font-size: 11px;
  color: #a9a9a9; 
  pointer-events: none;
