/*「愛の叙事集」(绿) by点星 禁止二传二改 */

/* ========== 仅聊天页面直接子顶栏生效，弹窗/二级页面完全隔离 ========== */
#chat-detail-screen > .chat-header-custom {
  /* ⭐全局顶栏高度 */
  --header-h: 170px;
  --chat-header-height: var(--header-h);
  --chat-header-bg: transparent;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;

  /* 装饰图配置 */
  --chat-deco-src: url('https://cn.atoilgas.com/uploads/20260709/5336a00a3b241cf3e4692556d2a94abd.png');
  --chat-deco-w: 270px;
  --chat-deco-h: auto;

  /* 头像全局参数 */
  --chat-header-avatar-border: none;
  --chat-header-avatar-shadow: none;
  --chat-header-unread-top: calc(var(--header-h) / 4);
  --chat-header-unread-num-top: calc(var(--header-h) / 4 - 4px);

  /* ⭐【调头像位置】 */
  --avatar-top: 34px; /* 数值越小，越往上 */
  --avatar-left: auto; 
  --avatar-right: 190px; /* 数值越小，越往右 */
  /* ⭐【调备注位置】 */
  --title-top: -11px; /* 数值越小，越往上 */
  --title-right: -105px; /* 数值越小，越往右 */
  --sub-top: 38px;
  --sub-right: 20px;
  --sub-max-width: 240px; 
}

/* 顶栏容器开启相对定位 */
#chat-detail-screen > .chat-header-custom {
  position: relative !important;
  min-height: var(--header-h) !important;
  background: transparent !important;
  overflow: visible !important;
}

/* 🎨 装饰图伪元素，盖住头像但 不盖备注 */
#chat-detail-screen > .chat-header-custom::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--chat-deco-src);
  background-size: var(--chat-deco-w) var(--chat-deco-h);
  background-position: center center;
  background-repeat: no-repeat;
  z-index: 5;
  pointer-events: none;
}

/* ⭐爱心头像位置 */
#chat-detail-screen > .chat-header-custom::after {
  content: "";
  position: absolute !important;
  z-index: 0 !important; /* 层级保持不变，低于装饰图 */
  top: 58px !important; /* 数值越小，越往上 */
  right: 58px !important; /* 数值越小，越往右 */
  width: 92px !important;
  height: 80px !important;

  /* 👇👇👇 关键在这里 👇👇👇
    请将您的图片上传到支持外链的图床后，再替换下面的 URL。*/
  background-image: url('https://ocs.celine.cn/livechat/uploadfile/celine/20260709/B21E5E7F7FBB7DEEE04913BFDCF616D4.jpg');

  background-size: contain !important;
  background-repeat: no-repeat !important;
  transform: rotate(0deg) !important;
  pointer-events: none !important;
}

/* 清空玻璃层背景 */
#chat-detail-screen > .glass-header {
  height: var(--header-h) !important;
  background: transparent !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ========== 🎯 头像容器：z-index:0 被装饰图盖住 ========== */
#chat-detail-screen > .chat-header-custom .header-profile-section {
  position: absolute !important;
  z-index: 0 !important;  /* 头像被装饰图盖住 */
  top: var(--avatar-top) !important;
  left: var(--avatar-left) !important;
  right: var(--avatar-right) !important;
  width: max-content;
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
}

/* ⭐头像 */
#chat-detail-screen > .chat-header-custom .header-avatar-container,
#chat-detail-screen > .chat-header-custom .chat-header-avatar {
  width: 95px !important;
  height: 117px !important;
  border-radius: 0px !important;
  border: none !important;
  outline: none !important;
  transform: rotate(-11deg) !important;
  overflow: visible !important;
}

/* ========== 📝 备注独立提高层级：不被装饰图盖住 ========== */
/* 标题 - 单独提高 z-index 到装饰图之上 */
#chat-detail-screen > .chat-header-custom .chat-header-title {
  position: absolute !important;
  z-index: 10 !important;  /* 比装饰图 z-index:5 高，不被盖住 */
  top: var(--title-top) !important;
  right: var(--title-right) !important;
  left: auto !important;
  text-align: right !important;
  font-size: 18px !important;
  font-weight: 700;
  color: #b5d6b5 !important;  /* 淡绿色 */
  white-space: nowrap;
}

/* 副标题 - 单独提高 z-index 到装饰图之上 */
#chat-detail-screen > .chat-header-custom .chat-header-subtitle {
  position: absolute !important;
  z-index: 10 !important;  /* 比装饰图 z-index:5 高，不被盖住 */
  top: var(--sub-top) !important;
  right: var(--sub-right) !important;
  left: auto !important;
  text-align: right !important;
  font-size: 13px;
  color: #b5d6b5 !important;  /* 淡绿色 */
  white-space: nowrap;
  max-width: var(--sub-max-width) !important;
