#chat-detail-screen > .chat-header-custom .header-btn-back {
  position: relative !important;
  z-index: 10 !important;
  margin: auto 0;
  /* 保留点击区域，即使图标隐藏 */
  min-width: 40px !important;
  min-height: 40px !important;
  cursor: pointer !important;
}

/* 消息列表顶部留白 */
#chat-detail-screen .chat-message-list-custom {
  padding-top: calc(max(env(safe-area-inset-top, 12px)) + var(--header-h) + 24px) !important;
}

