}

/* ---- 3. 🎯 核心逻辑：侦测系统状态，精准剔除不需要的图标 ---- */

/* 对方：只保留第一条 */
.msg-them.is-mid .bubble-them-custom::after,
.msg-them.is-last .bubble-them-custom::after,
.bubble-them-custom.is-mid::after,
.bubble-them-custom.is-last::after,
.msg-them:has(.is-mid) .bubble-them-custom::after,
.msg-them:has(.is-last) .bubble-them-custom::after {
