/* ==========================================
   🎯 装饰图标 & 无缝边框 (双方统一连体边框)
   ========================================== */

/* ---- 1. 我方气泡基础设置 ---- */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  /* 👉 给我方加上淡灰色无缝连体边框 */
  filter: drop-shadow(1px 0 0 #e0e0e0)
          drop-shadow(-1px 0 0 #e0e0e0)
          drop-shadow(0 1px 0 #e0e0e0)
          drop-shadow(0 -1px 0 #e0e0e0) !important;
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  bottom: -6px;
  right: -3px;
  width: 19.5px;   /* 👈 从 19px 调大一点 */
  height: 19.5px;  /* 👈 从 19px 调大一点 */
  background-color: var(--bubble-me-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(0deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 2. 对方气泡基础设置 ---- */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  /* 👉 给对方也加上同样的淡灰色无缝连体边框 */
  filter: drop-shadow(1px 0 0 #e0e0e0)
          drop-shadow(-1px 0 0 #e0e0e0)
          drop-shadow(0 1px 0 #e0e0e0)
          drop-shadow(0 -1px 0 #e0e0e0) !important;
}
.bubble-them-custom::after {
  content: "";
  position: absolute;
  top: -6px;
  left: -3px;
  width: 19.5px;   /* 👈 从 19px 调大一点 */
  height: 19.5px;  /* 👈 从 19px 调大一点 */
  background-color: var(--bubble-them-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(45deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 3. 🎯 核心逻辑：侦测系统状态，精准剔除不需要的图标 ---- */

/* 对方：只保留第一条 */
.msg-them.is-mid .bubble-them-custom::after,
.msg-them.is-last .bubble-them-custom::after,
