:root {
  /* 底栏整体完全纯透明，无任何边框、模糊 */
  --input-area-bg: transparent;
  --input-area-blur: 0px;
  --input-area-border-top: none;
  --input-area-padding: 8px 12px;
  --input-area-min-height: 73px !important;

  /* 彻底移除输入胶囊边框、背景、圆角，完全无框 */
  --input-box-bg: transparent;
  --input-box-blur: none;
  --input-box-radius: 0px;
  --input-box-border: none;
  --input-box-padding: 8px 16px 8px 0px;
  --input-box-color: #222;
  --input-box-placeholder: transparent;
  --input-caret-color: #222;

  /* 按钮基础色 全部黑色系 */
  --plus-btn-color: #222;
  --input-btn-color: #444;
  --send-btn-color: #0095f6;
  --send-btn-bg: transparent;
  --send-btn-radius: 0px;
  --send-btn-size: 32px;
}

/* 底栏外层：纯透明，无边框无阴影 */
.input-area-custom {
  background: transparent !important;
  backdrop-filter: none !important;
  border-top: none !important;
  box-shadow: none !important;
  padding: var(--input-area-padding) !important;
  min-height: 73px !important;
}

/* 主输入行：必须 relative，作为 absolute 参照 */
.input-row-wrapper {
  display: flex !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  gap: 10px !important;
  position: relative !important;
  width: 100%;
}

/* ========== 加号按钮：隐藏图标，保留点击 ========== */
.input-btn-plus {
  width: 28px !important;
  height: 28px !important;
  flex-shrink: 0;
  background: transparent !important;
  border: none !important;
  position: relative !important;
}
.input-btn-plus svg {
  display: none !important;
}
.input-btn-plus::before {
