:root {
  /* ---- 我方气泡：白色 ---- */
  --bubble-me-bg: #ffffff;
  --bubble-me-color: #1a1a1a;
  --bubble-me-padding: 5.5px 9.5px;  /* 👈 从 5px 9px 调大一点 */
  --bubble-me-font-size: 12.8px;     /* 👈 从 12.5px 调大一点 */
  --bubble-me-line-height: 1.28;     /* 👈 从 1.25 调大一点 */
  --bubble-me-radius: 13.5px;        /* 👈 从 13px 调大一点 */
  --bubble-me-radius-first: 13.5px 13.5px 4px 13.5px;
  --bubble-me-radius-mid: 13.5px 4px 4px 13.5px;
  --bubble-me-radius-last: 13.5px 4px 13.5px 13.5px;
  --bubble-me-shadow: none;
  --bubble-me-border: none;

  /* ---- 对方气泡：中等淡灰 ---- */
  --bubble-them-bg: #eeeeee;
  --bubble-them-color: #1a1a1a;
  --bubble-them-padding: 5.5px 9.5px;  /* 👈 从 5px 9px 调大一点 */
  --bubble-them-font-size: 12.8px;     /* 👈 从 12.5px 调大一点 */
  --bubble-them-line-height: 1.28;     /* 👈 从 1.25 调大一点 */
  --bubble-them-radius: 13.5px;        /* 👈 从 13px 调大一点 */
  --bubble-them-radius-first: 13.5px 13.5px 13.5px 4px;
  --bubble-them-radius-mid: 4px 13.5px 13.5px 4px;
  --bubble-them-radius-last: 4px 13.5px 13.5px 13.5px;
  --bubble-them-shadow: none;
  --bubble-them-border: none;

  --chat-message-max-width: 64%;      /* 👈 从 62.5% 调大一点 */
  --bubble-me-link-color: #0095f6;
  --bubble-them-link-color: #0095f6;

  /* ==========================================
     转账卡片 - 底色跟随各自气泡底色
     ========================================== */
  --transfer-card-bg: #ffffff;
  --transfer-me-card-bg: var(--bubble-me-bg);
  --transfer-me-card-border: none;
  --transfer-me-card-shadow: none;
  --transfer-them-card-bg: var(--bubble-them-bg);
  --transfer-them-card-border: none;
  --transfer-them-card-shadow: none;
  --transfer-success-card-bg: var(--bubble-me-bg);
  --transfer-rejected-card-bg: var(--bubble-me-bg);
  --transfer-expired-card-bg: var(--bubble-me-bg);
  --transfer-card-radius: 13.5px;     /* 👈 从 13px 调大一点 */
  --transfer-card-shadow: none;
  --transfer-card-border: none;
}

/* ⭐头像旁文字标签(To/By) */

/* ---- 对方头像右侧加 "To xa" ---- */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after {
  content: "To 小安" !important;
  position: absolute !important;
  left: calc(100% + 6px) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 12px !important;
  color: #999999 !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 对方头像容器需要相对定位 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  position: relative !important;
}

/* ---- 我方头像左侧加 "By dx" ---- */
.msg-avatar-me-container.is-last::before,
.msg-avatar-me-container.is-single::before {
  content: "By 点星" !important;
  position: absolute !important;
  right: calc(100% + 6px) !important;
