  font-size: 12px !important;
  color: #999999 !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 我方头像容器需要相对定位 */
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  position: relative !important;
}

/* ==========================================
   🎯 装饰图标 & 无缝边框 (双方统一连体边框)
   ========================================== */

/* ---- 1. 我方气泡基础设置 ---- */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  /* 👉 给我方加上淡灰色无缝连体边框 */
  filter: drop-shadow(1px 0 0 #e0e0e0)
          drop-shadow(-1px 0 0 #e0e0e0)
          drop-shadow(0 1px 0 #e0e0e0)
          drop-shadow(0 -1px 0 #e0e0e0) !important;
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  bottom: -6px;
  right: -3px;
  width: 19.5px;   /* 👈 从 19px 调大一点 */
  height: 19.5px;  /* 👈 从 19px 调大一点 */
  background-color: var(--bubble-me-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(0deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 2. 对方气泡基础设置 ---- */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  /* 👉 给对方也加上同样的淡灰色无缝连体边框 */
  filter: drop-shadow(1px 0 0 #e0e0e0)
          drop-shadow(-1px 0 0 #e0e0e0)
          drop-shadow(0 1px 0 #e0e0e0)
          drop-shadow(0 -1px 0 #e0e0e0) !important;
}
.bubble-them-custom::after {
  content: "";
  position: absolute;
  top: -6px;
  left: -3px;
  width: 19.5px;   /* 👈 从 19px 调大一点 */
  height: 19.5px;  /* 👈 从 19px 调大一点 */
  background-color: var(--bubble-them-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(45deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 3. 🎯 核心逻辑：侦测系统状态，精准剔除不需要的图标 ---- */

/* 对方：只保留第一条 */
.msg-them.is-mid .bubble-them-custom::after,
.msg-them.is-last .bubble-them-custom::after,
.bubble-them-custom.is-mid::after,
.bubble-them-custom.is-last::after,
.msg-them:has(.is-mid) .bubble-them-custom::after,
.msg-them:has(.is-last) .bubble-them-custom::after {
  display: none !important;
}

/* 我方：只保留最后一条 */
.msg-me.is-first .bubble-me-custom::after,
.msg-me.is-mid .bubble-me-custom::after,
.bubble-me-custom.is-first::after,
.bubble-me-custom.is-mid::after,
.msg-me:has(.is-first) .bubble-me-custom::after,
.msg-me:has(.is-mid) .bubble-me-custom::after {
  display: none !important;
}

/* ==========================================
   特殊消息处理（图片/表情/转账卡片）
   ========================================== */

.msg-me .msg-transfer-card {
  background: var(--bubble-me-bg) !important;
  border: none !important;
  box-shadow: none !important;
}
.msg-them .msg-transfer-card {
  background: var(--bubble-them-bg) !important;
  border: none !important;
  box-shadow: none !important;
}

.bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::after,
.msg-me:has(.no-padding) .bubble-me-custom::after,
.msg-them:has(.no-padding) .bubble-them-custom::after,
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::after,
.bubble-me-custom:has([class*="sticker"])::after,
.bubble-them-custom:has([class*="sticker"])::after,
.bubble-me-custom:has([class*="emoji"])::after,
.bubble-them-custom:has([class*="emoji"])::after {
    display: none !important;
}

/* 图片/表情气泡本身透明化并去除边框和滤镜 */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has([class*="sticker"]),
.bubble-them-custom:has([class*="sticker"]),
.bubble-me-custom:has([class*="emoji"]),
.bubble-them-custom:has([class*="emoji"]) {
