/* ==========================================
   🎯 连续气泡间距缩小 (只挤压气泡，不碰头像)
   ========================================== */

/* 第一条：减小它底部的间距，让它贴近下一条 */
.msg-me.is-first, .msg-them.is-first,
.msg-me:has(.is-first), .msg-them:has(.is-first) {
  margin-bottom: 2.2px !important;
}

/* 中间条：减小它上下两端的间距，让它紧贴上下气泡 */
.msg-me.is-mid, .msg-them.is-mid,
.msg-me:has(.is-mid), .msg-them:has(.is-mid) {
  margin-top: 2.2px !important;
  margin-bottom: 2.2px !important;
}

/* 最后一条：减小它顶部的间距，让它贴近上一条 */
.msg-me.is-last, .msg-them.is-last,
.msg-me:has(.is-last), .msg-them:has(.is-last) {
  margin-top: 2.2px !important;
}

/* ==========================================
   🌐 翻译独立气泡（干净微调版）
   ========================================== */

/* 1. 隐藏气泡内部的翻译 */
.msg-translation-wrapper {
  display: none !important;
}

