/* 🌟 翻译小尾巴 */
.msg-translation-detached-content {
  padding-bottom: 25px !important;
  position: relative !important;
}
.msg-translation-detached-content::after {
  content: "由微信提供翻译支持";
  position: absolute !important;
  left: 28px !important;
  bottom: 10px !important;
  font-size: 11px !important;
  color: #b2b2b2 !important;
  line-height: 12px !important;
  pointer-events: none !important;
}
.msg-translation-detached-content::before {
  content: "";
  position: absolute !important;
  left: 12px !important;
  bottom: 10px !important;
  width: 12px !important;
  height: 12px !important;
  background-color: #c9c9c9 !important;
  border-radius: 50% !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" stroke="%23F5F5F5" stroke-linecap="round"><line x1="6" y1="13" x2="10" y2="17" stroke-width="2.5"/><line x1="10" y1="17" x2="18" y2="8" stroke-width="1.5"/></svg>') !important;
  background-size: 12px 12px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
/* 给独立翻译气泡加个“保底宽度”，防止短句把底部小字挤换行 */
.msg-translation-detached,
.msg-translation-detached-content {
  min-width: 140px !important;
}

/* 顺手给底部小字加个不换行保护 */
.msg-translation-detached-content::after {
  white-space: nowrap !important;
}
@media (prefers-color-scheme: dark) {
  body .msg-translation-detached-content::after {
    color: #8e8e93 !important;
  }
  body .msg-translation-detached-content::before {
    background-color: #bcbcbc !important;
  }
}

/* =================================== */
/*  🍓转账卡片 by小Q怡 */
/* =================================== */
:root{
  --transfer-card-bg:#FA9D3B;
  --transfer-card-bg-received:#FCE2BC;
  --transfer-card-bg-expired:#E6C7A5;
  --transfer-icon-default:url('https://i.postimg.cc/j5CqLH5J/wu-biao-ti38-20260205143013.png');
  --transfer-icon-received:url('https://nos.netease.com/ysf/032ae26e2e69a232d3bb904047b34e38.png');
  --transfer-icon-returned:url('https://nos.netease.com/ysf/0b5a28d77f1934fdcc6750fd8f9897c6.png');
  --transfer-icon-expired:url('https://nos.netease.com/ysf/dfbb30c0b7383f9209c03597b101adfe.png');
