  --call-text-connected:"通话时长 ";
}
.msg-videocall-card,
.msg-videocall-card.missed,
.msg-videocall-card.connected,
.msg-videocall-card.cancelled,
.msg-videocall-card.rejected{
  width:fit-content!important;
  min-width:0!important;
  max-width:240px!important;
  padding:6px 10px!important;
  border-radius:4px!important;
  box-shadow:none!important;
  border:none!important;
  display:flex!important;
  align-items:center!important;
  gap:8px!important;
  position:relative!important;
  cursor:default!important;
  /* 默认（对方）颜色 */
  background: var(--call-card-bg-them) !important;
  background-color: var(--call-card-bg-them) !important;
}
:is(.msg-me, .bubble-me-custom) :is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected),
:is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected).msg-me {
  background: var(--call-card-bg-me) !important;
  background-color: var(--call-card-bg-me) !important;
}
:is(.msg-them, .bubble-them-custom) :is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected),
:is(.msg-videocall-card, .msg-videocall-card.missed, .msg-videocall-card.connected, .msg-videocall-card.cancelled, .msg-videocall-card.rejected).msg-them {
  background: var(--call-card-bg-them) !important;
  background-color: var(--call-card-bg-them) !important;
}
.msg-me .msg-videocall-card::after,
.bubble-me-custom .msg-videocall-card::after,
.msg-videocall-card.msg-me::after{
  content:""!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  left:auto!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background:var(--call-card-bg-me)!important;
  background-color:var(--call-card-bg-me)!important;
  border-radius:2px!important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
}
.msg-them .msg-videocall-card::before,
.bubble-them-custom .msg-videocall-card::before,
.msg-videocall-card.msg-them::before{
  content:""!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  right:auto!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background:var(--call-card-bg-them)!important;
  background-color:var(--call-card-bg-them)!important;
  border-radius:2px!important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
}

.msg-videocall-card > div:first-child{
  width:24px!important;
  height:24px!important;
  min-width:24px!important;
  min-height:24px!important;
  border-radius:0!important;
