.stop-btn-custom svg {
  opacity: 0 !important;
}
.stop-btn-custom::before {
  content: "♥" !important;
  font-size: 20px !important;
  color: rgba(255, 255, 255, 0.45) !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
