}

/* 确保头像不会被影响 */
.msg-avatar-them-container img,
.msg-avatar-me-container img,
.msg-avatar-container img,
[class*="avatar"] img {
   max-width: none !important;
   max-height: none !important;
   width: 100% !important;
   height: 100% !important;
   object-fit: cover !important;
}
/* AI打字中的气泡也往下推 */

/* 打字中气泡：直接给wrapper里的第一个实际内容往下推 */
.msg-bubble-wrapper.msg-them.is-first:not(:has(.nuo-thinking-wrap)) > .msg-content-stack,
.msg-bubble-wrapper.msg-them.is-single:not(:has(.nuo-thinking-wrap)) > .msg-content-stack {
  padding-top: 0 !important;  /* 没有思维链时，内容区已经被wrapper的padding-top推下去了，这里不用再加 */
}
/*  核心：只缩小引用里的表情包，保持消息气泡里的正常 */

/* 引用区域里的表情包缩小 */
.msg-reply-block-detached img,
.msg-reply-block img {
  max-width: 50px !important;
  max-height: 50px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
}

/* 消息气泡里的表情包保持正常（不缩小） */
[class*="msg-sticker"]:not(.msg-reply-block-detached *) img,
[class*="sticker"]:not(.msg-reply-block-detached *) img {
  max-width: none !important;
  max-height: none !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
}

/* ============================================
    转账卡片：窄长方形+全白文字+无边框
   ============================================ */
.msg-transfer-card,
[class*="transfer-card"] {
  background: rgba(40, 40, 40, 0.4) !important;
  border: none !important;
  border-radius: 10px !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  box-shadow: none !important;
  padding: 4px 12px !important;
  max-width: 240px !important;
  min-height: auto !important;
}

.msg-transfer-card [class*="amount"],
.msg-transfer-card .transfer-amount,
.msg-transfer-card [class*="title"],
.msg-transfer-card [class*="note"],
.msg-transfer-card .transfer-title,
.msg-transfer-card .transfer-note,
.msg-transfer-card * {
  color: #ffffff !important;
}

.msg-transfer-card svg,
.msg-transfer-card [class*="icon"] {
  color: rgba(255, 255, 255, 0.7) !important;
  stroke: rgba(255, 255, 255, 0.7) !important;
}

/* ============================================
   🖼️ 表情包 + 图片处理（引用时缩小表情包，但不影响消息内图片）
   ============================================ */

/* 所有消息里的img默认去掉边框 */
.msg-image-wrapper,
.msg-transfer-card,
.gift-ig-container,
[class*="msg-sticker"],
[class*="sticker"] {
  border: none !important;
}

/* 🔧 消息里发送的图片（非表情包）保持原样 */
.msg-image-wrapper img {
  max-width: 100% !important;
  max-height: none !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border: none !important;
}

/* 🔧 头像不受任何影响 */
.msg-avatar-them-container img,
.msg-avatar-me-container img,
.msg-avatar-container img,
[class*="avatar"] img {
  max-width: none !important;
  max-height: none !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}
/*=========================================
   特殊消息自动隐藏气泡
========================================= */

/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 补丁：如果气泡里同时有引用块，恢复气泡显示 */
.bubble-me-custom:has(.msg-reply-block-detached, .msg-reply-block),
.bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block) {
  background-color: var(--bubble-me-bg) !important;
  background: var(--bubble-me-bg) !important;
  padding: var(--bubble-me-padding) !important;
  border: var(--bubble-me-border) !important;
  box-shadow: var(--bubble-me-shadow) !important;
}

.bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block) {
  background-color: var(--bubble-them-bg) !important;
  background: var(--bubble-them-bg) !important;
  padding: var(--bubble-them-padding) !important;
  border: var(--bubble-them-border) !important;
  box-shadow: var(--bubble-them-shadow) !important;
  backdrop-filter: var(--bubble-them-backdrop) !important;
  -webkit-backdrop-filter: var(--bubble-them-backdrop) !important;
}

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

value.css:
/* 淡淡的就会顺顺的紫色 — nuojiji messaging app theme */

/* ========== 1. 全局色彩与变量 ========== */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
--nj-msg-bg: #ffffff;
--nj-msg-moments-bg: #ffffff;
--nj-msg-profile-bg: #ffffff;
--nj-msg-fav-bg: #ffffff;
--nj-msg-card-bg: #ffffff; /* 你说吸色是白色，我改成纯白了 */
--nj-msg-card-bg-pinned: #ffffff;
--nj-msg-card-radius: 16px;
--nj-msg-card-border: 1px solid #f2effa;
--nj-msg-text: #4d4c66;
--nj-msg-text-muted: #8e8ea1;
--nj-msg-text-time: #d2c4f2;
--nj-msg-avatar-radius: 50%;
--nj-msg-avatar-shadow: none;
--nj-msg-tabbar-active: #d2c4f2;
--nj-msg-tabbar-bg: rgba(255, 255, 255, 0.85);
--show-top-star: block;
}
/* ========== 2. 顶栏与搜索框 (终极坐标钉死版) ========== */
#messaging-chat-tab {
display: flex !important;
flex-direction: column !important;
--nj-msg-chat-bg: #fcfcfc !important;
}
.nj-chat-tab-header {
background: rgba(255, 255, 255, 1) !important;
border-bottom: 1px solid #f2effa !important;
box-shadow: none !important;
backdrop-filter: none !important;
-webkit-backdrop-filter: none !important;
height: calc(40px + var(--nuo-safe-top)) !important;
padding: 0 !important;
position: sticky !important;
top: 0 !important;
z-index: 100 !important;
}
.nj-chat-tab-header-title-btn {
color: transparent !important;
}
.nj-chat-tab-header::after {
content: 'WeChat';
position: absolute !important;
left: 50% !important;
top: calc(15px + var(--nuo-safe-top)) !important;
transform: translate(-50%, -50%) !important;
font-size: 17px !important;
font-weight: 500 !important;
color: #4d4c66 !important;
pointer-events: none !important;
}
.nj-chat-tab-header-edit svg { display: none !important; }
.nj-chat-tab-header-edit {
background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%234d4c66" stroke-width="1.5" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="9.5"></circle><path d="M12 7.5v9M7.5 12h9"></path></svg>');
background-size: 22px;
background-repeat: no-repeat;
background-position: center;
width: 24px !important;
height: 24px !important;
position: absolute !important;
right: 16px !important;
top: calc(15px + var(--nuo-safe-top)) !important;
transform: translateY(-50%) !important;
}
.nj-chat-tab-header-back svg { display: none !important; }
.nj-chat-tab-header-back {
opacity: 1 !important;
display: var(--show-top-star) !important;
background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%234d4c66" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" xmlns="http://www.w3.org/2000/svg"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>');
background-size: 22px;
background-repeat: no-repeat;
background-position: center;
width: 24px !important;
height: 24px !important;
position: absolute !important;
left: 16px !important;
top: calc(15px + var(--nuo-safe-top)) !important;
transform: translateY(-50%) !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-back { filter: invert(1) !important; }
.nj-chat-tab-search {
background: #ffffff !important;
border-radius: 7px !important;
margin: 0px -11px 5px -11px !important;
height: 34px !important;
box-shadow: 0 0px 12px rgba(0, 0, 0, 0.01) !important;
border: none !important;
display: flex !important;
align-items: center !important;
justify-content: center !important;
padding: 0 12px !important;
position: relative !important;
}
.nj-chat-tab-search > svg { display: none !important; }
.nj-chat-tab-search::after {
content: '搜索';
position: absolute !important;
left: 0 !important;
right: 0 !important;
top: 0 !important;
bottom: 0 !important;
background-color: #ffffff !important;
border-radius: 7px !important;
z-index: 10 !important;
display: flex !important;
justify-content: center !important;
align-items: center !important;
color: #b2b2b2 !important;
font-size: 15px !important;
pointer-events: none !important;
padding-left: 20px !important;
background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23999999" stroke-width="2" xmlns="http://www.w3.org/2000/svg"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>');
background-repeat: no-repeat !important;
background-size: 15px !important;
background-position: calc(50% - 17px) calc(50% - 1px) !important;
}
.nj-chat-tab-search:focus-within::after { display: none !important; }
/* ========== 3. 连体胶囊列表 ========== */
.nj-chat-tab-list {
background: transparent !important;
padding-top: 8px !important;
}
.nj-chat-item {
margin: 0 16px !important;
border-radius: 0 !important;
box-shadow: none !important;
border-bottom: none !important;
position: relative !important;
}
.nj-chat-item-pinned { background-color: #ffffff !important; }
.nj-chat-item-pinned:first-child { border-radius: 16px 16px 0 0 !important; }
.nj-chat-item-pinned:not(:has(+ .nj-chat-item-pinned)) {
border-radius: 0 0 16px 16px !important;
margin-bottom: 32px !important;
box-shadow: 0 4px 12px rgba(209, 196, 242, 0.15) !important;
padding-bottom: 18px !important;
}
.nj-chat-item-pinned:first-child:not(:has(+ .nj-chat-item-pinned)) { border-radius: 16px !important; }
.nj-chat-item:not(.nj-chat-item-pinned) { background-color: #ffffff !important; }
.nj-chat-item-pinned + .nj-chat-item:not(.nj-chat-item-pinned),
.nj-chat-item:not(.nj-chat-item-pinned):first-child {
border-radius: 16px 16px 0 0 !important;
}
.nj-chat-item:not(.nj-chat-item-pinned):last-child {
border-radius: 0 0 16px 16px !important;
margin-bottom: 16px !important;
box-shadow: 0 4px 12px rgba(209, 196, 242, 0.15) !important;
padding-bottom: 18px !important;
}
/* ========== 4. 细节修饰 ========== */
.nj-chat-item-avatar {
width: 52px !important;
height: 52px !important;
border: 2px solid #d2c4f2 !important;
padding: 2px !important;
background-color: #ffffff !important;
box-sizing: border-box !important;
border-radius: 50% !important;
}
.nj-chat-item-time {
font-size: 11.5px !important;
font-weight: 420 !important;
opacity: 0.5 !important;
transform: translateY(-4px) !important;
}
.nj-chat-item-pinned:not(:has(+ .nj-chat-item-pinned))::before,
.nj-chat-item:not(.nj-chat-item-pinned):last-child::before {
content: "";
position: absolute;
left: 20px;
right: 20px;
bottom: 8px;
border-bottom: 1px dashed rgba(209, 196, 242, 0.6) !important;
pointer-events: none;
z-index: 10;
}
.nj-chat-item-name::before {
content: "@";
color: #d2c4f2 !important;
margin-right: 2px !important;
font-weight: normal !important;
}
.nj-chat-item-pinned .nj-chat-item-avatar {
position: relative !important;
overflow: visible !important;
}
.nj-chat-item-pinned .nj-chat-item-avatar::after {
content: "★";
position: absolute;
top: -3px;
left: -3px;
width: 15px;
height: 15px;
background-color: #E2D6F4;
color: #fff;
font-size: 13px;
font-weight: bold;
border-radius: 50%;
display: flex !important;
align-items: center !important;
justify-content: center !important;
border: 2px solid #fff;
z-index: 10;
}
.nj-chat-item:not(.nj-chat-item-pinned) .nj-chat-item-avatar::after {
content: "+";
position: absolute;
top: -3px;
left: -3px;
width: 14px;
height: 14px;
background-color: #E2D6F4;
color: #fff;
font-size: 17px;
font-weight: bold;
border-radius: 50%;
display: flex !important;
align-items: center !important;
justify-content: center !important;
border: 2px solid #fff;
z-index: 10;
line-height: 14px !important;
text-indent: 1px !important;
}
.nj-chat-item-name {
margin-bottom: -2px !important;
}
.nj-chat-item-preview {
margin-top: 4px !important;
margin-right: 16px !important;
text-overflow: ellipsis !important;
display: block !important;
white-space: nowrap !important;
overflow: hidden !important;
}
/* ========== 5. 隐藏不需要的元素 ========== */
.nj-chat-tab-section-title { display: none !important; }
.nj-chat-tab-notes { display: none !important; }
.nj-chat-item-pin-mark { display: none !important; }
#messaging-chat-tab .nj-chat-item::after { display: none !important; }
/* ========== 6. 搜索栏下方的心情胶囊 ========== */
.nj-chat-tab-decor-mid {
height: auto !important;
width: calc(100% - 32px) !important;
display: flex !important;
align-items: center !important;
box-sizing: border-box !important;
margin: -2px 16px 6px 16px !important;
padding: 10px 14px !important;
background: #ffffff !important;
border-radius: 16px !important;
border: 1px solid #f2effa !important;
box-shadow: 0 2px 8px rgba(209, 196, 242, 0.15) !important;
}
.nj-chat-tab-decor-mid::before {
content: ">ㅅ<";
background: #FCF7FE !important;
color: #c8b5ed !important;
padding: 6px 12px !important;
border-radius: 12px !important;
font-size: 12px !important;
font-weight: bold !important;
flex-shrink: 0 !important;
margin-left: 16px !important;
}
.nj-chat-tab-decor-mid::after {
content: "TuT ˶>ヮ<˶";
flex: 1 !important;
margin-left: 16px !important;
color: #4d4c66 !important;
font-size: 13px !important;
text-align: center !important;
word-spacing: 44px !important;
}
/* ========== 7. 置顶胶囊顶部爱心虚线 ========== */
.nj-chat-item-pinned:first-child {
padding-top: 30px !important;
}
.nj-chat-item-pinned:first-child::after {
content: " ┈┈┈┈ ♥ ┈┈┈┈ ♡ ┈┈┈┈ ♥ ┈┈┈┈";
display: block !important;
position: absolute;
top: 4px;
left: 0;
right: 0;
text-align: center;
color: #dfd6f5;
font-size: 13px;
letter-spacing: 2px;
pointer-events: none;
}
/* ========== 8. 置顶与非置顶分割标记 ========== */
.nj-chat-item-pinned + .nj-chat-item:not(.nj-chat-item-pinned)::after {
content: "✧ Messages" !important;
display: block !important;
position: absolute !important;
top: -24px !important;
left: 8px !important;
color: #dfd6f5 !important;
font-size: 12px !important;
font-weight: bold !important;
letter-spacing: 1px !important;
pointer-events: none !important;
}
/* ========== 9. 悬浮胶囊底栏 ========== */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
--nj-msg-tabbar-active: #d2c4f2 !important;
--nj-msg-tabbar-inactive: #dfd6f5 !important;
--nj-msg-unread-bg: #d2c4f2 !important;
}
.nj-tab-bottom-bar {
background: rgba(255, 255, 255, 0.9) !important;
backdrop-filter: blur(20px) !important;
-webkit-backdrop-filter: blur(20px) !important;
border: 1px solid #f2effa !important;
border-radius: 30px !important;
width: auto !important;
left: 18px !important;
right: 18px !important;
bottom: calc(-14px + var(--nuo-safe-bottom)) !important;
margin: 0 !important;
padding: 4px 0 !important;
box-shadow: 0 4px 16px rgba(209, 196, 242, 0.2) !important;
}
.nj-tab-bottom-total-unread,
.nj-tab-bottom-moments-dot {
border: 1px solid #ffffff !important;
}
.nj-tab-bottom-item {
display: flex !important;
flex-direction: column !important;
justify-content: center !important;
align-items: center !important;
gap: 0px !important;
margin-top: 0px
}
.nj-tab-bottom-item::after {
font-size: 9px !important;
font-weight: bold !important;
color: var(--nj-msg-tabbar-inactive) !important;
letter-spacing: 0.5px !important;
}
.nj-tab-bottom-item-active::after {
color: var(--nj-msg-tabbar-active) !important;
}
.nj-tab-bottom-item-chat::after { content: 'Chats'; }
.nj-tab-bottom-item-moments::after { content: 'Moments'; }
.nj-tab-bottom-item-favorites::after { content: 'Space'; }
.nj-tab-bottom-item-profile::after { content: 'Me'; }
/* ========== 10. 底栏图标 ========== */
.nj-tab-bottom-icon svg { display: none !important; }
.nj-tab-bottom-icon {
width: 26px !important;
height: 26px !important;
background-size: contain !important;
background-repeat: no-repeat !important;
background-position: center !important;
margin-bottom: 2px !important;
}
.nj-tab-bottom-item-chat .nj-tab-bottom-icon {
background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23E2D6F4" stroke-width="1.5" xmlns="http://www.w3.org/2000/svg"><path d="M12 3c5.52 0 10 3.8 10 8.5 0 2.76-1.5 5.2-3.88 6.82-.16.1-.26.28-.24.47l.3 2.1c.04.25-.22.42-.42.27l-2.4-1.68c-.14-.1-.32-.12-.48-.08C13.97 19.8 13 20 12 20c-5.52 0-10-3.8-10-8.5S6.48 3 12 3z"/></svg>') !important;
}
.nj-tab-bottom-item-chat.nj-tab-bottom-item-active .nj-tab-bottom-icon {
background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="%23E2D6F4" xmlns="http://www.w3.org/2000/svg"><path d="M12 3c5.52 0 10 3.8 10 8.5 0 2.76-1.5 5.2-3.88 6.82-.16.1-.26.28-.24.47l.3 2.1c.04.25-.22.42-.42.27l-2.4-1.68c-.14-.1-.32-.12-.48-.08C13.97 19.8 13 20 12 20c-5.52 0-10-3.8-10-8.5S6.48 3 12 3z"/></svg>') !important;
}
.nj-tab-bottom-item-moments .nj-tab-bottom-icon {
